-- ============================================================================
-- BASELINE SCHEMA SNAPSHOT — not a replay of history.
--
-- This migration captures the live production schema of project
-- linqsojbszglbgpoxgtv as it existed on 2026-09-24, generated by querying
-- Postgres system catalogs directly (pg_get_functiondef, pg_get_triggerdef,
-- pg_get_constraintdef, pg_get_viewdef, pg_policy, cron.job, etc.) because no
-- pg_dump/CLI-dump access was available in this environment.
--
-- It is NOT a chronological record of how the schema evolved — that history
-- lives in the ~145 untracked migrations this project accumulated between
-- 2026-04-07 and 2026-08-27, most of which were never committed to this repo.
-- This file exists so a fresh Supabase project can be brought from empty to
-- schema-complete in one pass. It sits BENEATH the existing tracked
-- migrations (which start 2026-08-27) — it does not replace, delete, or
-- reconcile any of them.
--
-- Deliberately excluded: all secrets and vault contents, Supabase-managed
-- internal schemas (auth, storage, realtime) except our own RLS policies on
-- storage.objects, and the 5 Supabase-platform-owned event triggers (only
-- our own `ensure_rls` event trigger is captured).
--
-- Statements are idempotent where Postgres allows it (CREATE ... IF NOT
-- EXISTS, CREATE OR REPLACE, DO-block guarded enum creation, DROP ... IF
-- EXISTS before re-creating constraints/policies) so this file can run
-- against a fresh project without erroring on a second run.
-- ============================================================================


-- ============================================================================
-- 1. EXTENSIONS
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_stat_statements WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;


-- ============================================================================
-- 2. ENUMS
-- ============================================================================

DO $$ BEGIN
  CREATE TYPE public.line_item_approval_status AS ENUM ('auto_approved', 'pending', 'approved', 'rejected');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.line_item_type AS ENUM ('labor', 'material', 'equipment', 'disposal', 'travel', 'permit', 'other');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.media_kind AS ENUM ('before', 'progress', 'after', 'receipt', 'document');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.payment_intent_status AS ENUM ('pending_hold', 'hold_failed', 'held', 'in_progress', 'contractor_completed', 'customer_finished', 'captured', 'released', 'refunded', 'disputed');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.work_order_event_type AS ENUM ('status_changed', 'line_item_added', 'line_item_approved', 'line_item_rejected', 'photo_uploaded', 'checklist_item_checked', 'payment_held', 'payment_updated', 'payment_captured', 'payment_voided', 'location_started', 'location_stopped', 'message_sent', 'change_order_submitted', 'change_order_approved', 'change_order_rejected', 'work_order_created', 'arrival_confirmed', 'job_completed', 'dispute_opened', 'dispute_resolved', 'note_added');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE public.work_order_status AS ENUM ('submitted', 'accepted', 'deposit_secured', 'en_route', 'arrived', 'in_progress', 'waiting_for_customer', 'materials_needed', 'change_order_pending', 'awaiting_approval', 'payment_releasing', 'completed', 'cancelled', 'disputed');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


-- ============================================================================
-- 3. SEQUENCES
-- ============================================================================

CREATE SEQUENCE IF NOT EXISTS public.wo_number_seq;
CREATE SEQUENCE IF NOT EXISTS public.work_order_number_seq;


