CREATE OR REPLACE FUNCTION public._finalize_job_acceptance(p_booking_id uuid, p_contractor_id uuid, p_contractor_name text, p_final_price numeric, p_offer_id uuid DEFAULT NULL::uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_booking_time text DEFAULT NULL::text)
 RETURNS TABLE(booking bookings, work_order work_orders)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booking public.bookings;
  v_existing_wo public.work_orders;
  v_work_order public.work_orders;
  v_verification_status text;
BEGIN
  SELECT verification_status INTO v_verification_status
  FROM public.contractors WHERE id = p_contractor_id;

  IF v_verification_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'Contractor is not verified' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_booking FROM public.bookings WHERE id = p_booking_id FOR UPDATE;

  IF v_booking IS NULL THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.status != 'pending' OR v_booking.contractor_id IS NOT NULL THEN
    RAISE EXCEPTION 'Job already taken' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.bookings
  SET contractor_id   = p_contractor_id,
      contractor_name = p_contractor_name,
      status          = 'confirmed',
      price_estimate  = COALESCE(p_final_price, price_estimate),
      scheduled_at    = COALESCE(p_scheduled_at, scheduled_at),
      booking_time    = COALESCE(p_booking_time, booking_time),
      accepted_at     = NOW(),
      confirmed_at    = NOW()
  WHERE id = p_booking_id
  RETURNING * INTO v_booking;

  IF p_offer_id IS NOT NULL THEN
    UPDATE public.job_offers
    SET status            = 'accepted',
        customer_action   = 'accepted',
        contractor_final  = 'accepted',
        final_price       = COALESCE(p_final_price, final_price)
    WHERE id = p_offer_id;
  END IF;

  SELECT * INTO v_existing_wo FROM public.work_orders WHERE booking_id = p_booking_id FOR UPDATE;

  IF v_existing_wo IS NULL THEN
    INSERT INTO public.work_orders (
      booking_id, contractor_id, customer_id, contractor_name, customer_name,
      service_type, job_address, status, wo_status
    )
    VALUES (
      p_booking_id, p_contractor_id, v_booking.customer_id, p_contractor_name,
      COALESCE(v_booking.customer_name, ''),
      v_booking.trade, COALESCE(v_booking.job_address, v_booking.notes, ''),
      'accepted', 'accepted'
    )
    RETURNING * INTO v_work_order;
  ELSE
    v_work_order := v_existing_wo;
  END IF;

  RETURN QUERY SELECT v_booking, v_work_order;
END;
$function$;


CREATE OR REPLACE FUNCTION public._send_new_job_email(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booking public.bookings;
  v_contractor RECORD;
BEGIN
  SELECT * INTO v_booking FROM public.bookings WHERE id = p_booking_id;
  IF NOT FOUND OR v_booking.contractor_id IS NOT NULL OR v_booking.status != 'pending' THEN
    RETURN;
  END IF;

  FOR v_contractor IN
    SELECT DISTINCT u.email
    FROM public.contractors c
    JOIN public.users u ON u.id = c.id
    WHERE c.is_available = true
      AND c.verification_status = 'approved'
      AND c.allow_notifications = true
      AND (c.notification_prefs ->> 'email_new_job') IS DISTINCT FROM 'false'
      AND u.email IS NOT NULL
      AND (v_booking.trade IS NULL OR EXISTS (
        SELECT 1 FROM public.contractor_trades ct WHERE ct.contractor_id = c.id AND ct.trade_id = v_booking.trade
      ))
  LOOP
    PERFORM public.send_email('new_job_nearby', v_contractor.email, jsonb_build_object(
      'trade', COALESCE(v_booking.trade,'Job'),
      'address', COALESCE(v_booking.job_address,'Near you'),
      'price', COALESCE(v_booking.price_estimate::TEXT,'—')
    ));
  END LOOP;

  UPDATE public.bookings SET job_email_sent_at = now() WHERE id = p_booking_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public._within_working_hours()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXTRACT(hour FROM now() AT TIME ZONE 'America/New_York') BETWEEN 8 AND 20;
$function$;


CREATE OR REPLACE FUNCTION public.accept_job(p_booking_id uuid, p_contractor_id uuid, p_contractor_name text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_owner BOOLEAN;
  v_is_authorized_employee BOOLEAN;
  v_is_instant_book BOOLEAN;
  v_result RECORD;
BEGIN
  v_is_owner := (auth.uid() = p_contractor_id);

  SELECT EXISTS (
    SELECT 1 FROM public.employees
    WHERE auth_user_id = auth.uid() AND company_id = p_contractor_id AND can_accept_jobs = true
  ) OR EXISTS (
    SELECT 1 FROM public.contractor_employees
    WHERE user_id = auth.uid() AND contractor_id = p_contractor_id
      AND status = 'active' AND can_accept_jobs = true
  ) INTO v_is_authorized_employee;

  IF NOT (v_is_owner OR v_is_authorized_employee) THEN
    RAISE EXCEPTION 'Not authorized to accept jobs for this contractor' USING ERRCODE = '42501';
  END IF;

  SELECT is_instant_book INTO v_is_instant_book FROM public.bookings WHERE id = p_booking_id;
  IF v_is_instant_book IS NOT TRUE THEN
    RAISE EXCEPTION 'This job requires a quote' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_result FROM public._finalize_job_acceptance(p_booking_id, p_contractor_id, p_contractor_name, NULL, NULL, NULL, NULL);

  RETURN v_result.booking;
END;
$function$;


CREATE OR REPLACE FUNCTION public.admin_process_refund(p_refund_id uuid, p_status text, p_amount_approved numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.users where id = auth.uid() and is_admin = true) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  update public.refund_requests
    set status = p_status, amount_approved = coalesce(p_amount_approved, amount_approved)
  where id = p_refund_id;
end $function$;


CREATE OR REPLACE FUNCTION public.admin_resolve_dispute(p_dispute_id uuid, p_status text, p_resolution text DEFAULT NULL::text, p_winner text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.users where id = auth.uid() and is_admin = true) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  update public.disputes set status = p_status, resolution = p_resolution, winner = p_winner where id = p_dispute_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.admin_review_verification(p_contractor_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_company_name text;
begin
  if not exists (select 1 from public.users where id = auth.uid() and is_admin = true) then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  perform set_config('app.bypass_protection', 'verification', true);

  update public.contractors set
    verification_status           = case when p_approve then 'approved' else 'rejected' end,
    approval_status                = case when p_approve then 'approved' else 'rejected' end,
    verified                       = p_approve,
    license_verified                = case when p_approve then true else license_verified end,
    insurance_verified              = case when p_approve then true else insurance_verified end,
    insured                         = case when p_approve then true else insured end,
    verification_rejection_reason  = case when p_approve then null else p_reason end,
    verification_reviewed_at       = now(),
    is_available                    = case when p_approve then is_available else false end,
    is_online                       = case when p_approve then is_online else false end
  where id = p_contractor_id
  returning company_name into v_company_name;

  update public.contractor_verification
    set status = case when p_approve then 'approved' else 'rejected' end
  where contractor_id = p_contractor_id;

  insert into public.notifications (user_id, type, title, message, data)
  values (
    p_contractor_id,
    case when p_approve then 'verification_approved' else 'verification_rejected' end,
    case when p_approve then 'Verification Approved ✅' else 'Verification Rejected' end,
    case when p_approve
      then 'Your contractor verification has been approved. You can now go online and accept jobs.'
      else 'Your contractor verification was rejected. Reason: ' || coalesce(p_reason, 'No reason provided.')
    end,
    jsonb_build_object('contractor_id', p_contractor_id, 'approved', p_approve, 'reason', p_reason)
  );

  insert into public.notifications (user_id, type, title, message, data)
  select
    u.id,
    case when p_approve then 'verification_approved' else 'verification_rejected' end,
    case when p_approve then 'Contractor Verified' else 'Contractor Verification Rejected' end,
    coalesce(v_company_name, 'A contractor') || ' (' || p_contractor_id::text || ')' ||
      case when p_approve then ' was approved.'
           else ' was rejected. Reason: ' || coalesce(p_reason, 'No reason provided.')
      end,
    jsonb_build_object('contractor_id', p_contractor_id, 'approved', p_approve, 'reason', p_reason)
  from public.users u
  where u.is_admin = true;
end $function$;


CREATE OR REPLACE FUNCTION public.admin_update_contractor_plan(p_contractor_id uuid, p_new_plan text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.users where id = auth.uid() and is_admin = true) then
    raise exception 'not authorized' using errcode = '42501';
  end if;

  if p_new_plan not in ('free', 'leads', 'pro') then
    raise exception 'invalid plan: %', p_new_plan using errcode = '22023';
  end if;

  perform set_config('app.bypass_protection', 'plan', true);

  update public.contractors set plan = p_new_plan where id = p_contractor_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.after_work_order_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO work_order_events (work_order_id, event_type, actor_id, label, payload)
  VALUES (
    NEW.id, 'work_order_created', auth.uid(),
    'Work order ' || NEW.work_order_number || ' created',
    jsonb_build_object('work_order_number', NEW.work_order_number, 'booking_id', NEW.booking_id)
  );
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.after_work_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_label text;
  v_old_status work_order_status := OLD.status;
  v_new_status work_order_status := COALESCE(NEW.wo_status, NEW.status);
BEGIN
  IF v_old_status = v_new_status THEN RETURN NEW; END IF;

  v_label := CASE v_new_status::text
    WHEN 'submitted'            THEN 'Work order submitted'
    WHEN 'accepted'             THEN 'Contractor accepted the job'
    WHEN 'deposit_secured'      THEN 'Deposit secured — payment held'
    WHEN 'en_route'             THEN 'Contractor is on the way'
    WHEN 'arrived'              THEN 'Contractor has arrived'
    WHEN 'in_progress'          THEN 'Work is in progress'
    WHEN 'waiting_for_customer' THEN 'Waiting for customer confirmation'
    WHEN 'materials_needed'     THEN 'Additional materials needed'
    WHEN 'change_order_pending' THEN 'Change order submitted — awaiting approval'
    WHEN 'awaiting_approval'    THEN 'Work complete — awaiting your approval'
    WHEN 'payment_releasing'    THEN 'Payment releasing'
    WHEN 'completed'            THEN 'Job completed'
    WHEN 'cancelled'            THEN 'Job cancelled'
    WHEN 'disputed'             THEN 'Dispute opened'
    ELSE 'Status updated to ' || v_new_status::text
  END;

  INSERT INTO work_order_events (work_order_id, event_type, actor_id, label, payload)
  VALUES (
    NEW.id, 'status_changed', auth.uid(), v_label,
    jsonb_build_object('from', v_old_status::text, 'to', v_new_status::text)
  );

  IF v_old_status = 'en_route' THEN
    DELETE FROM contractor_locations WHERE work_order_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.apply_reliability_penalty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.contractors
  set
    reliability_score = greatest(0, coalesce(reliability_score, 100) - new.points),
    penalty_count     = coalesce(penalty_count, 0) + 1
  where id::text = new.contractor_id;
  -- Auto-suspend if score drops below 40
  update public.contractors
  set approval_status = 'suspended', is_available = false
  where id::text = new.contractor_id and coalesce(reliability_score, 100) < 40;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.auto_approve_new_contractor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Auto-approve so new contractors show up instantly
  -- Admin can manually reject from admin dashboard
  IF NEW.approved IS NULL OR NEW.approved = false THEN
    NEW.approved := true;
    NEW.approval_status := 'pending'; -- pending review but visible
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.before_line_item_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_pending_count integer;
  v_event_type    work_order_event_type;
  v_event_label   text;
BEGIN
  IF OLD.approval_status = NEW.approval_status THEN RETURN NEW; END IF;

  -- Set approved_at timestamp
  IF NEW.approval_status IN ('approved','auto_approved') THEN
    NEW.approved_at := now();
  END IF;

  IF NEW.work_order_id IS NULL THEN RETURN NEW; END IF;

  -- Count remaining pending items (excluding current row — still OLD in table)
  SELECT COUNT(*) INTO v_pending_count
  FROM payment_line_items
  WHERE work_order_id = NEW.work_order_id
    AND approval_status = 'pending'
    AND id != NEW.id;

  -- If last pending item resolved, pop work order back to in_progress
  IF v_pending_count = 0 AND NEW.approval_status IN ('approved','rejected') THEN
    UPDATE work_orders
    SET status = 'in_progress', updated_at = now()
    WHERE id = NEW.work_order_id AND status = 'change_order_pending';
  END IF;

  -- Timeline event
  IF NEW.approval_status = 'approved' THEN
    v_event_type  := 'change_order_approved';
    v_event_label := 'Change order approved: ' || NEW.label;
  ELSIF NEW.approval_status = 'rejected' THEN
    v_event_type  := 'change_order_rejected';
    v_event_label := 'Change order rejected: ' || NEW.label;
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO work_order_events (work_order_id, event_type, actor_id, label, payload)
  VALUES (NEW.work_order_id, v_event_type, auth.uid(), v_event_label,
    jsonb_build_object('line_item_id', NEW.id, 'amount_cents', NEW.amount_cents));

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.before_line_item_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_wo_id                uuid;
  v_wo_status            work_order_status;
  v_auto_approve_under   integer;
  v_event_type           work_order_event_type;
  v_event_label          text;
BEGIN
  SELECT id, status, auto_approve_under_cents
  INTO v_wo_id, v_wo_status, v_auto_approve_under
  FROM work_orders WHERE payment_intent_id = NEW.payment_intent_id
  LIMIT 1;

  IF v_wo_id IS NULL THEN RETURN NEW; END IF;

  -- Block additions to terminal states
  IF v_wo_status IN ('completed','cancelled','disputed') THEN
    RAISE EXCEPTION 'Cannot add line items to a % work order', v_wo_status;
  END IF;

  NEW.work_order_id := v_wo_id;

  -- Determine approval status
  IF NOT NEW.requires_approval THEN
    NEW.approval_status := 'auto_approved';
    NEW.approved_at     := now();
  ELSIF v_auto_approve_under > 0 AND NEW.amount_cents <= v_auto_approve_under THEN
    NEW.approval_status := 'auto_approved';
    NEW.approved_at     := now();
  ELSE
    NEW.approval_status := 'pending';
  END IF;

  -- Push work order into change_order_pending if approval needed during active work
  IF NEW.approval_status = 'pending'
     AND v_wo_status IN ('arrived','in_progress','waiting_for_customer','materials_needed') THEN
    UPDATE work_orders SET status = 'change_order_pending', updated_at = now()
    WHERE id = v_wo_id;
    v_event_type  := 'change_order_submitted';
    v_event_label := 'Change order submitted: ' || NEW.label;
  ELSE
    v_event_type  := 'line_item_added';
    v_event_label := NEW.label || ' added';
  END IF;

  INSERT INTO work_order_events (work_order_id, event_type, actor_id, label, payload)
  VALUES (v_wo_id, v_event_type, auth.uid(), v_event_label,
    jsonb_build_object(
      'label',            NEW.label,
      'amount_cents',     NEW.amount_cents,
      'item_type',        NEW.item_type::text,
      'requires_approval',NEW.requires_approval,
      'approval_status',  NEW.approval_status::text
    ));

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.broadcast_new_job_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fuzzed record;
BEGIN
  IF NEW.status = 'pending'
     AND NEW.contractor_id IS NULL
     AND NEW.is_public = true
     AND NEW.trade IS NOT NULL
     AND NEW.job_lat IS NOT NULL
     AND NEW.job_lng IS NOT NULL
  THEN
    SELECT * INTO v_fuzzed
    FROM public.fuzz_point(NEW.id, NEW.job_lat::double precision, NEW.job_lng::double precision, 600);

    PERFORM realtime.send(
      jsonb_build_object(
        'id',                 NEW.id,
        'trade',               NEW.trade,
        'description',         NEW.description,
        'urgency',             NEW.urgency,
        'status',              NEW.status,
        'price_estimate',      NEW.price_estimate,
        'created_at',          NEW.created_at,
        'request_expires_at',  NEW.request_expires_at,
        'fuzzed_lat',          v_fuzzed.fuzzed_lat,
        'fuzzed_lng',          v_fuzzed.fuzzed_lng,
        'town',                NEW.town,
        'nearest_major_road',  NEW.nearest_major_road,
        'is_instant_book',     NEW.is_instant_book,
        'instant_book_price',  NEW.instant_book_price
      ),
      'new_lead',
      'leads:' || NEW.trade,
      true
    );
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.cancel_booking(p_booking_id uuid, p_reason text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_row public.bookings;
  v_existing public.bookings;
  v_role_label TEXT;
BEGIN
  SELECT * INTO v_existing FROM public.bookings WHERE id = p_booking_id;
  IF v_existing IS NULL THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  v_role_label := CASE
    WHEN v_existing.customer_id = auth.uid() THEN 'customer'
    WHEN v_existing.contractor_id = auth.uid() THEN 'contractor'
    ELSE NULL
  END;

  UPDATE public.bookings
  SET status        = 'cancelled',
      cancelled_at  = NOW(),
      cancel_reason = p_reason,
      cancelled_by  = v_role_label
  WHERE id = p_booking_id
    AND (customer_id = auth.uid() OR contractor_id = auth.uid())
    AND status NOT IN ('completed','cancelled')
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Booking not found, already finalized, or not yours to cancel' USING ERRCODE = '42501';
  END IF;

  RETURN v_row;
END;
$function$;


CREATE OR REPLACE FUNCTION public.check_employee_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_plan          TEXT;
  v_limit         INTEGER;
  v_current_count INTEGER;
BEGIN
  SELECT plan INTO v_plan
  FROM public.contractors
  WHERE id = NEW.contractor_id;

  SELECT employee_accounts INTO v_limit
  FROM public.plan_limits
  WHERE plan = COALESCE(v_plan, 'free');

  SELECT COUNT(*) INTO v_current_count
  FROM public.contractor_employees
  WHERE contractor_id = NEW.contractor_id
    AND status IN ('invited', 'active');

  -- -1 means unlimited (Pro plan)
  IF v_limit != -1 AND v_current_count >= v_limit THEN
    RAISE EXCEPTION 'Employee limit reached for % plan. Limit: %. Upgrade to add more employees.',
      COALESCE(v_plan, 'free'), v_limit;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.check_pin_matches(p_company_id uuid, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_hash TEXT;
BEGIN
  SELECT company_pin_hash INTO v_hash
  FROM public.contractors WHERE id = p_company_id;

  IF v_hash IS NULL THEN RETURN FALSE; END IF;

  RETURN v_hash = crypt(p_pin, v_hash);
END;
$function$;


CREATE OR REPLACE FUNCTION public.contractor_coverage_summary(user_lat double precision, user_lng double precision, radius_miles double precision DEFAULT 25)
 RETURNS TABLE(trade text, contractor_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH eligible AS (
    SELECT c.id, c.trade_type
    FROM contractors c
    WHERE c.lat IS NOT NULL AND c.lng IS NOT NULL
      AND c.is_available = true
      AND c.verification_status = 'approved'
      AND c.profile_published = true
      AND c.show_on_map = true
      AND haversine_miles(user_lat, user_lng, c.lat::float8, c.lng::float8)
          <= GREATEST(radius_miles, 1)
  ),
  per_trade AS (
    SELECT DISTINCT e.id, trim(t) AS trade
    FROM eligible e
    CROSS JOIN LATERAL unnest(string_to_array(e.trade_type, ',')) AS t
    WHERE trim(t) <> ''
  )
  SELECT trade, count(*) AS contractor_count
  FROM per_trade
  GROUP BY trade
  HAVING count(*) >= 3
  ORDER BY contractor_count DESC, trade ASC;
$function$;


CREATE OR REPLACE FUNCTION public.contractor_distances_miles(p_contractor_ids uuid[], user_lat double precision, user_lng double precision)
 RETURNS TABLE(id uuid, distance_miles double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.id, haversine_miles(user_lat, user_lng, c.lat::float8, c.lng::float8)
  FROM contractors c
  WHERE c.id = ANY(p_contractor_ids)
    AND c.lat IS NOT NULL AND c.lng IS NOT NULL;
$function$;


CREATE OR REPLACE FUNCTION public.contractor_respond_counter(p_offer_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_offer job_offers%ROWTYPE;
  v_contractor_name text;
  v_result RECORD;
BEGIN
  SELECT * INTO v_offer FROM job_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offer not found'; END IF;
  IF v_offer.contractor_id != auth.uid() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF v_offer.status != 'countered' THEN RAISE EXCEPTION 'No active counter to respond to'; END IF;
  IF v_offer.counter_expires_at IS NOT NULL AND v_offer.counter_expires_at < NOW() THEN
    UPDATE job_offers SET status = 'expired' WHERE id = p_offer_id;
    RAISE EXCEPTION 'The counter offer has expired';
  END IF;
  IF p_action = 'accepted' THEN
    SELECT company_name INTO v_contractor_name FROM public.contractors WHERE id = v_offer.contractor_id;
    SELECT * INTO v_result FROM public._finalize_job_acceptance(
      v_offer.booking_id, v_offer.contractor_id, COALESCE(v_contractor_name, ''), v_offer.counter_price, p_offer_id,
      v_offer.scheduled_at, v_offer.booking_time
    );
  ELSIF p_action = 'declined' THEN
    UPDATE job_offers SET contractor_final = 'declined', status = 'declined' WHERE id = p_offer_id;
  ELSE
    RAISE EXCEPTION 'Invalid action';
  END IF;
END;
$function$;


CREATE OR REPLACE FUNCTION public.contractor_trades_maintain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contractor_id uuid := COALESCE(NEW.contractor_id, OLD.contractor_id);
  v_primary_name text;
BEGIN
  IF TG_OP = 'DELETE' AND OLD.is_primary THEN
    UPDATE contractor_trades
    SET is_primary = true
    WHERE contractor_id = v_contractor_id
      AND trade_id = (
        SELECT trade_id FROM contractor_trades
        WHERE contractor_id = v_contractor_id
        ORDER BY sort_order ASC, trade_id ASC
        LIMIT 1
      );
  END IF;

  SELECT ct.trade_id INTO v_primary_name
  FROM contractor_trades ct
  WHERE ct.contractor_id = v_contractor_id AND ct.is_primary = true;

  UPDATE contractors SET trade_type = v_primary_name WHERE id = v_contractor_id;

  RETURN COALESCE(NEW, OLD);
END;
$function$;


CREATE OR REPLACE FUNCTION public.contractors_nearby(user_lat double precision, user_lng double precision, max_miles double precision DEFAULT 50, trade_filter text DEFAULT NULL::text, specialty_filter text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, company_name text, trade_type text, location text, service_area text, rating numeric, review_count integer, verified boolean, verification_status text, is_available boolean, plan text, avatar_url text, banner_url text, specializations jsonb, years_in_business integer, distance_miles double precision, pin_lat double precision, pin_lng double precision, pin_mode text, service_radius_miles numeric, area_label text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    c.id, c.company_name, c.trade_type, c.location, c.service_area,
    c.rating, c.review_count, c.verified, c.verification_status,
    c.is_available, c.plan, c.avatar_url, c.banner_url,
    c.specializations, c.years_in_business,
    haversine_miles(user_lat, user_lng, c.lat::float8, c.lng::float8) as distance_miles,
    pcl.pin_lat, pcl.pin_lng, pcl.pin_mode, pcl.service_radius_miles, pcl.area_label
  FROM contractors c
  CROSS JOIN LATERAL public.public_contractor_location(
    c.lat::float8, c.lng::float8, c.service_radius_miles,
    COALESCE(NULLIF(c.location, ''), NULLIF(c.business_city, ''), NULLIF(c.service_area, '')),
    c.show_exact_location, c.has_commercial_address, c.commercial_lat, c.commercial_lng
  ) pcl
  WHERE
    c.lat IS NOT NULL AND c.lng IS NOT NULL
    AND c.deleted_at IS NULL
    AND c.is_available = true
    AND c.verification_status = 'approved'
    AND c.profile_published = true
    AND c.show_on_map = true
    AND haversine_miles(user_lat, user_lng, c.lat::float8, c.lng::float8)
        <= coalesce(c.service_radius_miles::float8, max_miles)
    AND (trade_filter IS NULL OR EXISTS (
      SELECT 1 FROM contractor_trades ct WHERE ct.contractor_id = c.id AND ct.trade_id = trade_filter
    ))
    AND (specialty_filter IS NULL OR c.specializations @> to_jsonb(array[specialty_filter]))
  ORDER BY distance_miles ASC;
$function$;


CREATE OR REPLACE FUNCTION public.customer_respond_offer(p_offer_id uuid, p_action text, p_counter_price numeric DEFAULT NULL::numeric, p_counter_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_offer job_offers%ROWTYPE;
  v_contractor_name text;
  v_result RECORD;
BEGIN
  SELECT * INTO v_offer FROM job_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offer not found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM bookings WHERE id = v_offer.booking_id AND customer_id = auth.uid()
  ) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF v_offer.status != 'quoted' OR v_offer.customer_action != 'pending' THEN
    RAISE EXCEPTION 'Offer is no longer available for response';
  END IF;
  IF v_offer.expires_at < NOW() THEN
    UPDATE job_offers SET status = 'expired' WHERE id = p_offer_id;
    RAISE EXCEPTION 'This offer has expired';
  END IF;
  IF p_action = 'accepted' THEN
    SELECT company_name INTO v_contractor_name FROM public.contractors WHERE id = v_offer.contractor_id;
    SELECT * INTO v_result FROM public._finalize_job_acceptance(
      v_offer.booking_id, v_offer.contractor_id, COALESCE(v_contractor_name, ''), v_offer.quoted_price, p_offer_id,
      v_offer.scheduled_at, v_offer.booking_time
    );
  ELSIF p_action = 'declined' THEN
    UPDATE job_offers SET customer_action = 'declined', status = 'declined' WHERE id = p_offer_id;
  ELSIF p_action = 'countered' THEN
    IF p_counter_price IS NULL THEN RAISE EXCEPTION 'Counter price is required'; END IF;
    IF p_counter_price < v_offer.quoted_price * 0.70 THEN
      RAISE EXCEPTION 'Counter must be at least 70%% of the quoted price ($%)',
        ROUND((v_offer.quoted_price * 0.70)::numeric, 2);
    END IF;
    UPDATE job_offers SET
      customer_action = 'countered', counter_price = p_counter_price,
      counter_note = p_counter_note, status = 'countered',
      counter_expires_at = NOW() + INTERVAL '2 hours'
    WHERE id = p_offer_id;
  ELSE
    RAISE EXCEPTION 'Invalid action';
  END IF;
END;
$function$;


CREATE OR REPLACE FUNCTION public.email_on_job_accepted()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_customer_email TEXT;
  v_contractor_email TEXT;
BEGIN
  IF NEW.contractor_id IS NOT NULL AND OLD.contractor_id IS NULL THEN

    SELECT email INTO v_customer_email FROM public.users WHERE id = NEW.customer_id;
    SELECT email INTO v_contractor_email FROM public.users WHERE id = NEW.contractor_id;

    PERFORM public.send_email('job_accepted_customer', v_customer_email, jsonb_build_object(
      'contractorName', COALESCE(NEW.contractor_name,'Your contractor'),
      'trade', COALESCE(NEW.trade,'service'),
      'address', COALESCE(NEW.job_address,'your address'),
      'priceEstimate', '$' || COALESCE(NEW.price_estimate::TEXT,'TBD')
    ));

    PERFORM public.send_email('job_accepted_contractor', v_contractor_email, jsonb_build_object(
      'customerName', COALESCE(NEW.customer_name,'Customer'),
      'trade', COALESCE(NEW.trade,'service'),
      'address', COALESCE(NEW.job_address,''),
      'priceEstimate', '$' || COALESCE(NEW.price_estimate::TEXT,'TBD')
    ));
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.email_on_job_completed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_customer_email TEXT;
BEGIN
  IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
    SELECT email INTO v_customer_email FROM public.users WHERE id = NEW.customer_id;

    PERFORM public.send_email('job_completed', v_customer_email, jsonb_build_object(
      'contractorName', COALESCE(NEW.contractor_name,'Your contractor'),
      'trade', COALESCE(NEW.trade,'service'),
      'total', '$' || COALESCE(NEW.final_price::TEXT, NEW.price_estimate::TEXT,'—'),
      'bookingId', NEW.id::TEXT
    ));
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.email_on_new_job_posted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.contractor_id IS NULL AND NEW.status = 'pending' THEN
    IF NEW.urgency = 'emergency' OR public._within_working_hours() THEN
      PERFORM public._send_new_job_email(NEW.id);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.email_on_new_message()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_email TEXT;
BEGIN
  SELECT email INTO v_email FROM public.users WHERE id = NEW.recipient_id;

  PERFORM public.send_email('new_message', v_email, jsonb_build_object(
    'senderName', COALESCE(NEW.sender_name,'Someone'),
    'preview', LEFT(COALESCE(NEW.body,''), 80)
  ));
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.email_on_verification_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_email TEXT;
BEGIN
  IF NEW.verification_status = 'approved' AND OLD.verification_status != 'approved' THEN
    SELECT email INTO v_email FROM public.users WHERE id = NEW.id;
    PERFORM public.send_email('verification_approved', v_email, jsonb_build_object(
      'name', COALESCE(NEW.company_name, NEW.legal_name, 'Contractor')
    ));
  ELSIF NEW.verification_status = 'rejected' AND OLD.verification_status != 'rejected' THEN
    SELECT email INTO v_email FROM public.users WHERE id = NEW.id;
    PERFORM public.send_email('verification_rejected', v_email, jsonb_build_object(
      'reason', COALESCE(NEW.verification_rejection_reason, 'Please review your submitted information.')
    ));
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.employee_limit_for_plan(p_plan text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE COALESCE(p_plan, 'free')
    WHEN 'free' THEN 3
    WHEN 'leads' THEN 10
    WHEN 'pro'  THEN 25
    ELSE 3
  END
$function$;


CREATE OR REPLACE FUNCTION public.enforce_booking_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (
    SELECT count(*) FROM public.bookings
    WHERE customer_id = NEW.customer_id
      AND created_at > now() - interval '10 minutes'
  ) >= 3 THEN
    RAISE EXCEPTION 'Too many job postings in a short time — please wait a few minutes and try again.' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.enforce_portfolio_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_limit INTEGER;
  v_count INTEGER;
BEGIN
  IF current_setting('app.bypass_protection', true) = 'true' THEN
    RETURN NEW;
  END IF;

  IF NEW.portfolio_photos IS DISTINCT FROM OLD.portfolio_photos AND auth.role() = 'authenticated' THEN
    SELECT photo_limit INTO v_limit FROM public.plan_limits WHERE plan = COALESCE(NEW.plan, 'free');
    v_count := jsonb_array_length(COALESCE(NEW.portfolio_photos, '[]'::jsonb));
    IF v_limit IS NOT NULL AND v_count > v_limit THEN
      RAISE EXCEPTION 'Portfolio photo limit (%) exceeded for % plan', v_limit, COALESCE(NEW.plan,'free') USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.enforce_pre_booking_message_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  has_active_booking boolean;
  sent_count integer;
BEGIN
  IF NEW.is_system THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM bookings
    WHERE status IN ('confirmed', 'in_progress', 'completed', 'approved', 'paid')
      AND (
        (customer_id = NEW.sender_id AND contractor_id = NEW.recipient_id) OR
        (customer_id = NEW.recipient_id AND contractor_id = NEW.sender_id)
      )
  ) INTO has_active_booking;

  IF has_active_booking THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO sent_count
  FROM messages
  WHERE chat_id = NEW.chat_id
    AND sender_id = NEW.sender_id
    AND is_system = false;

  IF sent_count >= 3 THEN
    RAISE EXCEPTION 'PRE_BOOKING_LIMIT_REACHED: book this contractor to keep messaging'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_cleanup_contractor_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF OLD.wo_status = 'en_route' AND NEW.wo_status != 'en_route' THEN
    DELETE FROM contractor_locations WHERE work_order_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_guard_wo_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- No-op — allow
  IF NEW.wo_status = OLD.wo_status THEN RETURN NEW; END IF;

  -- Terminal escape valves — always allowed
  IF NEW.wo_status IN ('cancelled', 'disputed') THEN RETURN NEW; END IF;

  -- Legal forward transitions
  IF NOT (
    (NEW.wo_status = 'accepted'              AND OLD.wo_status IN ('submitted'))
    OR (NEW.wo_status = 'deposit_secured'    AND OLD.wo_status IN ('accepted', 'submitted'))
    OR (NEW.wo_status = 'en_route'           AND OLD.wo_status IN ('deposit_secured', 'accepted', 'submitted'))
    OR (NEW.wo_status = 'arrived'            AND OLD.wo_status IN ('en_route', 'deposit_secured'))
    OR (NEW.wo_status = 'in_progress'        AND OLD.wo_status IN ('arrived', 'accepted', 'deposit_secured', 'en_route', 'waiting_for_customer', 'materials_needed', 'change_order_pending', 'submitted'))
    OR (NEW.wo_status = 'waiting_for_customer' AND OLD.wo_status IN ('in_progress'))
    OR (NEW.wo_status = 'materials_needed'   AND OLD.wo_status IN ('in_progress'))
    OR (NEW.wo_status = 'change_order_pending' AND OLD.wo_status IN ('in_progress', 'arrived'))
    OR (NEW.wo_status = 'awaiting_approval'  AND OLD.wo_status IN ('in_progress', 'arrived', 'change_order_pending'))
    OR (NEW.wo_status = 'payment_releasing'  AND OLD.wo_status IN ('awaiting_approval', 'in_progress'))
    OR (NEW.wo_status = 'completed'          AND OLD.wo_status IN ('payment_releasing', 'awaiting_approval', 'in_progress'))
  ) THEN
    RAISE EXCEPTION 'Invalid work order status transition: % → %', OLD.wo_status, NEW.wo_status;
  END IF;

  -- Money-state consistency: deposit_secured requires a held payment
  IF NEW.wo_status = 'deposit_secured' AND NEW.payment_intent_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM payment_intents
      WHERE id = NEW.payment_intent_id
        AND status NOT IN ('held', 'in_progress', 'contractor_completed', 'customer_finished', 'captured')
    ) THEN
      RAISE EXCEPTION 'Cannot set deposit_secured: payment hold not confirmed';
    END IF;
  END IF;

  -- Money-state consistency: completed requires captured payment
  IF NEW.wo_status = 'completed' AND NEW.payment_intent_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM payment_intents
      WHERE id = NEW.payment_intent_id
        AND status NOT IN ('captured', 'customer_finished', 'released')
    ) THEN
      RAISE EXCEPTION 'Cannot complete work order: payment not captured';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_handle_change_order_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_wo record;
BEGIN
  IF OLD.approval_status = NEW.approval_status THEN RETURN NEW; END IF;
  IF NEW.work_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_wo FROM work_orders WHERE id = NEW.work_order_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  IF NEW.approval_status = 'approved' THEN
    NEW.approved_by := auth.uid();
    NEW.approved_at := now();
    -- Resume work
    UPDATE work_orders
    SET wo_status = 'in_progress'
    WHERE id = NEW.work_order_id AND wo_status = 'change_order_pending';

    INSERT INTO work_order_events(work_order_id, event_type, actor_id, actor_role, label, payload)
    VALUES (NEW.work_order_id, 'change_order_approved', auth.uid(), 'customer',
            'Change order approved: ' || NEW.label,
            jsonb_build_object('amount_cents', NEW.amount_cents));

    BEGIN
      INSERT INTO notifications(user_id, type, title, message, data)
      VALUES (v_wo.contractor_id, 'change_order_approved', 'Change Order Approved',
              'Customer approved: ' || NEW.label,
              jsonb_build_object('work_order_id', NEW.work_order_id));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  IF NEW.approval_status = 'rejected' THEN
    NEW.rejected_by := auth.uid();
    NEW.rejected_at := now();
    -- Resume work without the extra line item
    UPDATE work_orders
    SET wo_status = 'in_progress'
    WHERE id = NEW.work_order_id AND wo_status = 'change_order_pending';

    INSERT INTO work_order_events(work_order_id, event_type, actor_id, actor_role, label, payload)
    VALUES (NEW.work_order_id, 'change_order_rejected', auth.uid(), 'customer',
            'Change order rejected: ' || NEW.label,
            jsonb_build_object('amount_cents', NEW.amount_cents));

    BEGIN
      INSERT INTO notifications(user_id, type, title, message, data)
      VALUES (v_wo.contractor_id, 'change_order_rejected', 'Change Order Rejected',
              'Customer rejected: ' || NEW.label,
              jsonb_build_object('work_order_id', NEW.work_order_id));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_handle_change_order_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_wo record;
BEGIN
  IF NEW.work_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_wo FROM work_orders WHERE id = NEW.work_order_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- Block additions after work is already wrapping up
  IF v_wo.wo_status IN ('awaiting_approval', 'payment_releasing', 'completed', 'cancelled', 'disputed') THEN
    RAISE EXCEPTION 'Cannot add line items after work is complete';
  END IF;

  -- Auto-approve if under the customer-set threshold
  IF NEW.requires_approval
     AND v_wo.auto_approve_under_cents > 0
     AND NEW.amount_cents <= v_wo.auto_approve_under_cents THEN
    NEW.approval_status  := 'auto_approved';
    NEW.requires_approval := false;
    RETURN NEW;
  END IF;

  -- Change order: set pending status + flip WO to change_order_pending
  IF NEW.requires_approval AND NEW.approval_status = 'pending' THEN
    UPDATE work_orders
    SET wo_status = 'change_order_pending'
    WHERE id = NEW.work_order_id;

    INSERT INTO work_order_events(work_order_id, event_type, actor_id, actor_role, label, payload)
    VALUES (
      NEW.work_order_id, 'change_order_submitted', NEW.added_by, 'contractor',
      'Change order submitted: ' || NEW.label,
      jsonb_build_object('amount_cents', NEW.amount_cents, 'item_type', NEW.item_type)
    );

    -- Notify customer
    BEGIN
      INSERT INTO notifications(user_id, type, title, message, data)
      VALUES (
        v_wo.customer_id, 'change_order',
        'Change Order Request',
        'Your contractor added work: ' || NEW.label || ' ($' || (NEW.amount_cents / 100)::text || ')',
        jsonb_build_object('work_order_id', NEW.work_order_id)
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_log_wo_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF OLD.wo_status IS DISTINCT FROM NEW.wo_status THEN
    INSERT INTO work_order_events(work_order_id, event_type, actor_role, label, payload)
    VALUES (
      NEW.id,
      'status_change',
      'system',
      CASE NEW.wo_status
        WHEN 'accepted'             THEN 'Job accepted by contractor'
        WHEN 'deposit_secured'      THEN 'Payment hold confirmed'
        WHEN 'en_route'             THEN 'Contractor is on the way'
        WHEN 'arrived'              THEN 'Contractor has arrived'
        WHEN 'in_progress'          THEN 'Work is underway'
        WHEN 'waiting_for_customer' THEN 'Waiting for customer'
        WHEN 'materials_needed'     THEN 'Contractor needs materials'
        WHEN 'change_order_pending' THEN 'Change order submitted — awaiting approval'
        WHEN 'awaiting_approval'    THEN 'Work complete — awaiting customer approval'
        WHEN 'payment_releasing'    THEN 'Payment releasing to contractor'
        WHEN 'completed'            THEN 'Job complete'
        WHEN 'cancelled'            THEN 'Job cancelled'
        WHEN 'disputed'             THEN 'Dispute opened'
        ELSE NEW.wo_status::text
      END,
      jsonb_build_object('from', OLD.wo_status, 'to', NEW.wo_status)
    );
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_progress_done_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_done AND NOT OLD.is_done THEN
    NEW.done_at := now();
  ELSIF NOT NEW.is_done AND OLD.is_done THEN
    NEW.done_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.fn_update_contractor_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contractor_id uuid;
BEGIN
  -- On DELETE, NEW is null; on INSERT/UPDATE, OLD may be null
  v_contractor_id := COALESCE(NEW.contractor_id, OLD.contractor_id);
  IF v_contractor_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  UPDATE public.contractors
  SET
    rating = (
      SELECT ROUND(AVG(rating_overall)::numeric, 1)
      FROM   public.reviews
      WHERE  contractor_id = v_contractor_id
    ),
    review_count = (
      SELECT COUNT(*)::integer
      FROM   public.reviews
      WHERE  contractor_id = v_contractor_id
    )
  WHERE id = v_contractor_id;

  RETURN COALESCE(NEW, OLD);
END;
$function$;


CREATE OR REPLACE FUNCTION public.fuzz_point(job_id uuid, point_lat double precision, point_lng double precision, radius_m double precision DEFAULT 600)
 RETURNS TABLE(fuzzed_lat double precision, fuzzed_lng double precision)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  WITH h AS (
    SELECT
      ('x' || substr(md5(job_id::text || ':lat'), 1, 8))::bit(32)::bigint / 4294967295.0 AS u,
      ('x' || substr(md5(job_id::text || ':lng'), 1, 8))::bit(32)::bigint / 4294967295.0 AS v
  )
  SELECT
    point_lat + (sqrt(v) * radius_m * cos(u * 2 * pi())) / 111132.0,
    point_lng + (sqrt(v) * radius_m * sin(u * 2 * pi())) / 84200.0
  FROM h;
$function$;


CREATE OR REPLACE FUNCTION public.generate_referral_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.referral_code := UPPER(SUBSTRING(REPLACE(NEW.id::text, '-', ''), 1, 8));
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.generate_work_order_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.work_order_number IS NULL THEN
    NEW.work_order_number :=
      'TE-' || to_char(now(), 'YYYY') || '-' ||
      lpad(nextval('work_order_number_seq')::text, 5, '0');
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_ranked_contractors(p_category text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_pro_priority_featured boolean DEFAULT false)
 RETURNS SETOF contractors
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.*
  FROM public.contractors c
  WHERE c.deleted_at IS NULL
    AND c.approval_status = 'approved'
    AND c.is_available = true
    AND (
      p_category IS NULL
      OR EXISTS (SELECT 1 FROM contractor_trades ct WHERE ct.contractor_id = c.id AND ct.trade_id = p_category)
    )
    AND (
      p_area IS NULL
      OR c.service_area ILIKE '%' || p_area || '%'
      OR c.location      ILIKE '%' || p_area || '%'
      OR c.business_city ILIKE '%' || p_area || '%'
    )
  ORDER BY
    CASE WHEN c.plan IN ('pro', 'leads') THEN 0 ELSE 1 END,
    CASE WHEN p_pro_priority_featured AND c.plan = 'pro' THEN 0 ELSE 1 END,
    random()
$function$;


CREATE OR REPLACE FUNCTION public.handle_booking_completed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'completed' and old.status != 'completed' then
    new.completed_at := now();
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.handle_cancellation_and_reassign()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_hours   numeric;
  v_rule    record;
  v_fee_pct int := 0;
  v_label   text := 'Free';
  v_by      text;
begin
  if new.status not in ('declined','cancelled') then return new; end if;
  if old.status = new.status then return new; end if;

  -- Determine who cancelled
  v_by := coalesce(new.cancelled_by,
    case when new.status = 'declined' then 'contractor' else 'customer' end);

  -- Calculate hours until booking
  if new.booking_date is not null then
    v_hours := extract(epoch from (
      (new.booking_date::timestamp + coalesce(new.booking_time, '09:00')::time) - now()
    )) / 3600.0;
  else
    v_hours := 999;
  end if;

  -- Customer cancellation = fee; contractor cancellation = no fee to customer
  if v_by = 'customer' then
    select * into v_rule from public.cancellation_rules
    where hours_before <= greatest(v_hours, 0)
    order by hours_before desc limit 1;
    if found then
      v_fee_pct := v_rule.fee_percent;
      v_label   := v_rule.label;
    end if;
  end if;

  -- Log cancellation -- reassign_needed removed, does not exist on this table
  insert into public.cancellations
    (booking_id, cancelled_by, hours_before, fee_percent, rule_applied, refund_status)
  values (
    new.id, v_by,
    round(v_hours::numeric, 1),
    v_fee_pct, v_label,
    case when v_fee_pct = 0 then 'na' else 'pending' end
  );

  -- Update booking fee fields
  new.cancelled_at    := now();
  new.fee_applied     := v_fee_pct > 0;
  new.fee_percent     := v_fee_pct;
  new.cancelled_by    := v_by;

  -- Notify the other party -- only if there is one
  if v_by = 'contractor' then
    insert into public.notifications (user_id, message, type, booking_id)
    values (
      new.customer_id,
      '⚠️ ' || coalesce(new.contractor_name, 'Your contractor') ||
      ' cancelled your booking. We are finding you a new contractor — check your bookings.',
      'booking_cancelled',
      new.id
    );
  elsif new.contractor_id is not null then
    -- Customer cancelled and a contractor was actually assigned. An
    -- unclaimed/expired job has no contractor_id -- nothing to notify.
    insert into public.notifications (user_id, message, type, booking_id)
    values (
      new.contractor_id::uuid,
      '❌ ' || coalesce(new.customer_name, 'A customer') ||
      ' cancelled their booking request.',
      'booking_cancelled_contractor',
      new.id
    );
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.haversine_miles(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  R     float8 := 3958.8;
  dlat  float8 := radians(lat2 - lat1);
  dlng  float8 := radians(lng2 - lng1);
  a     float8;
BEGIN
  a := sin(dlat/2)^2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)^2;
  RETURN R * 2 * asin(sqrt(LEAST(1.0, a)));
END;
$function$;


CREATE OR REPLACE FUNCTION public.issue_coupon_on_contractor_cancel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'cancelled'
     AND (OLD.status IS DISTINCT FROM 'cancelled')
     AND NEW.cancel_fee_recipient = 'owner'
     AND NEW.customer_id IS NOT NULL THEN
    INSERT INTO public.customer_coupons (user_id, source_booking_id)
    VALUES (NEW.customer_id, NEW.id);
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.mark_slot_booked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.status = 'accepted' and new.booking_date is not null and new.booking_time is not null then
    update public.time_slots
    set is_booked = true, booking_id = new.id
    where contractor_id = new.contractor_id
      and slot_date     = new.booking_date
      and slot_start    = new.booking_time::time;
  end if;
  -- If declined or cancelled, free the slot back up
  if new.status in ('declined','cancelled') then
    update public.time_slots
    set is_booked = false, booking_id = null
    where booking_id = new.id;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.mark_work_order_paid(p_work_order_id uuid, p_stripe_payment_intent_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows integer;
BEGIN
  IF p_stripe_payment_intent_id IS NULL OR p_stripe_payment_intent_id !~ '^pi_' THEN
    RAISE EXCEPTION 'Invalid stripe_payment_intent_id format';
  END IF;

  UPDATE public.work_orders
  SET status = 'completed',
      paid_at = NOW(),
      stripe_payment_intent_id = p_stripe_payment_intent_id
  WHERE id = p_work_order_id
    AND status = 'payment_releasing';

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'mark_work_order_paid: no row updated for work_order_id=% (not at payment_releasing, or does not exist)', p_work_order_id;
  END IF;
END;
$function$;


CREATE OR REPLACE FUNCTION public.mirror_status_to_wo_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.status is distinct from OLD.status
     and NEW.wo_status is distinct from NEW.status then
    NEW.wo_status := NEW.status;
  end if;
  return NEW;
end
$function$;


CREATE OR REPLACE FUNCTION public.mirror_wo_status_to_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.wo_status is distinct from OLD.wo_status
     and NEW.status is distinct from NEW.wo_status then
    NEW.status := NEW.wo_status;
  end if;
  return NEW;
end
$function$;


CREATE OR REPLACE FUNCTION public.nearby_jobs(contractor_lat numeric, contractor_lng numeric, max_distance_miles numeric DEFAULT 50, filter_trade text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, trade text, description text, job_lat numeric, job_lng numeric, price_estimate integer, booking_time text, urgency text, customer_name text, created_at timestamp with time zone, distance_miles numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    b.id,
    b.trade,
    b.description,
    b.job_lat,
    b.job_lng,
    b.price_estimate,
    b.booking_time,
    b.urgency,
    b.customer_name,
    b.created_at,
    ROUND(
      (3959 * acos(
        cos(radians(contractor_lat)) *
        cos(radians(b.job_lat)) *
        cos(radians(b.job_lng) - radians(contractor_lng)) +
        sin(radians(contractor_lat)) *
        sin(radians(b.job_lat))
      ))::numeric, 1
    ) AS distance_miles
  FROM public.bookings b
  WHERE b.job_lat IS NOT NULL
    AND b.job_lng IS NOT NULL
    AND b.status = 'pending'
    AND b.contractor_id IS NULL
    AND (filter_trade IS NULL OR b.trade = filter_trade)
    AND (3959 * acos(
        cos(radians(contractor_lat)) *
        cos(radians(b.job_lat)) *
        cos(radians(b.job_lng) - radians(contractor_lng)) +
        sin(radians(contractor_lat)) *
        sin(radians(b.job_lat))
      )) <= max_distance_miles
  ORDER BY b.created_at DESC
  LIMIT 100;
END;
$function$;


CREATE OR REPLACE FUNCTION public.notify_booking_status_supplemental()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;

  -- Contractor started the job → notify customer
  IF NEW.status = 'in_progress' AND NEW.customer_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
    VALUES (
      NEW.customer_id,
      'job_in_progress',
      '🔧 Work Has Started',
      COALESCE(NEW.contractor_name, 'Your contractor') || ' has started your '
        || COALESCE(NEW.trade, 'job') || '. You''ll be notified when it''s done.',
      jsonb_build_object('booking_id', NEW.id),
      'construct-outline',
      NEW.contractor_name
    );

  -- Customer cancelled → notify the assigned contractor
  ELSIF NEW.status = 'cancelled'
    AND NEW.contractor_id IS NOT NULL
    AND COALESCE(NEW.cancelled_by, '') = 'customer' THEN
    INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
    VALUES (
      NEW.contractor_id,
      'job_cancelled',
      '⚠️ Booking Cancelled',
      COALESCE(NEW.customer_name, 'The customer') || ' cancelled the '
        || COALESCE(NEW.trade, 'job') || ' booking.',
      jsonb_build_object('booking_id', NEW.id),
      'close-circle-outline',
      NEW.customer_name
    );

  -- Contractor declined → notify customer
  ELSIF NEW.status = 'declined' AND NEW.customer_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
    VALUES (
      NEW.customer_id,
      'job_declined',
      '❌ Booking Declined',
      COALESCE(NEW.contractor_name, 'A contractor') || ' declined your '
        || COALESCE(NEW.trade, 'job') || ' request. Try another contractor.',
      jsonb_build_object('booking_id', NEW.id),
      'close-circle-outline',
      NEW.contractor_name
    );
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.notify_contractor_new_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  -- Only notify if a contractor is actually assigned at insert time.
  -- Open jobs posted to the job board have no contractor yet — skip.
  if new.contractor_id is null then
    return new;
  end if;

  insert into public.notifications (user_id, message, type, booking_id)
  values (
    new.contractor_id::uuid,
    '📅 New booking request from ' || coalesce(new.customer_name, 'a customer') ||
    ' for ' || coalesce(to_char(new.booking_date, 'Mon DD'), 'an upcoming date') ||
    case when new.booking_time is not null then ' at ' || new.booking_time else '' end,
    'booking_new',
    new.id
  );
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.notify_employee_invited()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_name TEXT;
BEGIN
  SELECT company_name INTO v_company_name
  FROM public.contractors WHERE id = NEW.contractor_id;

  IF NEW.user_id IS NOT NULL THEN
