CREATE OR REPLACE FUNCTION public.notify_new_job_posted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.contractor_id IS NULL AND NEW.status = 'pending' THEN
    IF NEW.job_lat IS NOT NULL AND NEW.job_lng IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
      SELECT n.id, 'new_job_nearby',
        '🔥 New ' || COALESCE(NEW.trade,'Job') || ' Nearby',
        COALESCE(NEW.job_address,'Near you') || ' — ' ||
          CASE WHEN NEW.price_estimate IS NOT NULL THEN 'Est. $' || NEW.price_estimate::TEXT ELSE 'Price TBD' END,
        jsonb_build_object('booking_id',NEW.id,'trade',NEW.trade),
        'flash-outline', NEW.customer_name
      FROM public.contractors_nearby(NEW.job_lat::float8, NEW.job_lng::float8, 50, NEW.trade, NULL) n;
    ELSE
      INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
      SELECT c.id, 'new_job_nearby',
        '🔥 New ' || COALESCE(NEW.trade,'Job') || ' Nearby',
        COALESCE(NEW.job_address,'Near you') || ' — ' ||
          CASE WHEN NEW.price_estimate IS NOT NULL THEN 'Est. $' || NEW.price_estimate::TEXT ELSE 'Price TBD' END,
        jsonb_build_object('booking_id',NEW.id,'trade',NEW.trade),
        'flash-outline', NEW.customer_name
      FROM public.contractors_public c
      WHERE c.is_available = true
        AND c.verification_status = 'approved'
        AND c.profile_published = true
        AND (NEW.trade IS NULL OR EXISTS (
          SELECT 1 FROM contractor_trades ct WHERE ct.contractor_id = c.id AND ct.trade_id = NEW.trade
        ));
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.notify_new_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid1 uuid;
  v_uid2 uuid;
  v_target uuid;
BEGIN
  IF NEW.chat_id IS NOT NULL THEN
    BEGIN
      v_uid1 := split_part(NEW.chat_id, '_', 1)::uuid;
      v_uid2 := split_part(NEW.chat_id, '_', 2)::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_uid1 := NULL;
      v_uid2 := NULL;
    END;
    IF v_uid1 IS NOT NULL AND v_uid2 IS NOT NULL THEN
      v_target := CASE WHEN v_uid1 = NEW.sender_id THEN v_uid2 ELSE v_uid1 END;
    END IF;
  END IF;

  -- Only notify the actual other party in this chat_id pair. Now that this
  -- runs SECURITY DEFINER (bypassing notifications' owner-scoped RLS by
  -- design), NEW.recipient_id can't be trusted at face value any more --
  -- messages' own RLS only checks sender_id = auth.uid(), so a client could
  -- otherwise set an unrelated recipient_id and force a notification onto
  -- an arbitrary user.
  IF v_target IS NOT NULL AND v_target = NEW.recipient_id THEN
    INSERT INTO public.notifications (user_id, type, title, message, data, icon, actor_name)
    VALUES (
      NEW.recipient_id, 'new_message', 'New Message 💬',
      COALESCE(NEW.sender_name,'Someone') || ': ' || LEFT(COALESCE(NEW.body,''),60),
      jsonb_build_object('chat_id',NEW.chat_id,'sender_id',NEW.sender_id),
      'chatbubble-outline', NEW.sender_name
    );
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.notify_refund_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if old.status = new.status then return new; end if;

  insert into public.notifications (user_id, message, type, booking_id)
  values (
    new.customer_id,
    case new.status
      when 'approved'     then '✅ Your refund request has been approved! Funds will be returned within 5–10 business days.'
      when 'denied'       then '❌ Your refund request was reviewed and denied. Contact support to escalate.'
      when 'under_review' then '🔍 Your refund request is under review. We''ll update you within 3–5 business days.'
      when 'refunded'     then '💰 Your refund has been processed! Check your original payment method.'
      else                     '📋 Your refund request status has been updated to: ' || new.status
    end,
    'refund_update',
    new.booking_id
  );

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.process_account_deletion(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_req record;
  v_uid uuid;
  v_is_contractor boolean;
  v_is_customer boolean;
  v_active_reason text;
  v_storage jsonb;
BEGIN
  SELECT * INTO v_req FROM account_deletion_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_pending');
  END IF;
  IF v_req.scheduled_delete_at > now() THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_due');
  END IF;

  v_uid := v_req.user_id;
  v_is_contractor := EXISTS(SELECT 1 FROM contractors WHERE id = v_uid);
  v_is_customer   := EXISTS(SELECT 1 FROM users WHERE id = v_uid);

  SELECT string_agg(reason, '; ') INTO v_active_reason FROM (
    SELECT 'active booking ' || id AS reason FROM bookings
      WHERE (customer_id = v_uid OR contractor_id = v_uid)
        AND status NOT IN ('completed','declined','cancelled')
    UNION ALL
    SELECT 'active work order ' || id FROM work_orders
      WHERE (customer_id = v_uid OR contractor_id = v_uid)
        AND status NOT IN ('completed','cancelled')
    UNION ALL
    SELECT 'held payment on booking ' || id FROM bookings
      WHERE (customer_id = v_uid OR contractor_id = v_uid)
        AND payment_status = 'held'
    UNION ALL
    SELECT 'unsettled payment_intent ' || pi.id FROM payment_intents pi
      JOIN bookings b ON b.id = pi.booking_id
      WHERE (b.customer_id = v_uid OR b.contractor_id = v_uid)
        AND pi.status NOT IN ('captured','released','refunded')
    UNION ALL
    SELECT 'open dispute ' || id FROM disputes
      WHERE (customer_id = v_uid OR contractor_id = v_uid)
        AND status <> 'resolved'
  ) reasons;

  IF v_active_reason IS NOT NULL THEN
    UPDATE account_deletion_requests
      SET defer_reason = v_active_reason, last_attempted_at = now()
      WHERE id = p_request_id;
    RETURN jsonb_build_object('deferred', true, 'reason', v_active_reason);
  END IF;

  UPDATE bookings    SET customer_name   = 'Deleted User' WHERE customer_id   = v_uid;
  UPDATE bookings    SET contractor_name = 'Deleted User' WHERE contractor_id = v_uid;
  UPDATE work_orders SET customer_name   = 'Deleted User' WHERE customer_id   = v_uid;
  UPDATE work_orders SET contractor_name = 'Deleted User' WHERE contractor_id = v_uid;
  UPDATE reviews     SET reviewer_name   = 'Former customer' WHERE customer_id = v_uid;
  UPDATE messages    SET sender_name     = 'Deleted User' WHERE sender_id = v_uid;

  DELETE FROM notifications         WHERE user_id = v_uid;
  DELETE FROM availability          WHERE contractor_id = v_uid;
  DELETE FROM contractor_schedule   WHERE contractor_id = v_uid;
  DELETE FROM contractor_locations  WHERE contractor_id = v_uid;
  DELETE FROM contractor_portfolio  WHERE contractor_id = v_uid;
  DELETE FROM contractor_trades     WHERE contractor_id = v_uid;
  DELETE FROM contractor_verification WHERE contractor_id = v_uid;
  DELETE FROM job_views             WHERE contractor_id = v_uid;
  DELETE FROM time_slots            WHERE contractor_id = v_uid;
  DELETE FROM subscriptions         WHERE contractor_id = v_uid;
  DELETE FROM portfolio_jobs        WHERE contractor_id = v_uid;
  DELETE FROM customer_coupons      WHERE user_id = v_uid;
  DELETE FROM job_match_logs        WHERE user_id = v_uid;
  DELETE FROM contact_messages      WHERE user_id = v_uid;
  DELETE FROM payment_waitlist      WHERE user_id = v_uid;
  DELETE FROM otp_codes             WHERE user_id = v_uid;
  DELETE FROM support_messages      WHERE user_id = v_uid;
  DELETE FROM contractor_employees  WHERE user_id = v_uid;
  DELETE FROM employees             WHERE auth_user_id = v_uid;

  SELECT jsonb_build_object(
    'avatars',             COALESCE((SELECT array_agg(name) FROM storage.objects WHERE bucket_id = 'avatars' AND name LIKE v_uid::text || '/%'), '{}'),
    'job-photos',          COALESCE((SELECT array_agg(name) FROM storage.objects WHERE bucket_id = 'job-photos' AND name LIKE v_uid::text || '/%'), '{}'),
    'portfolio',            COALESCE((SELECT array_agg(name) FROM storage.objects WHERE bucket_id = 'portfolio' AND name LIKE v_uid::text || '/%'), '{}'),
    'portfolio-completed', COALESCE((SELECT array_agg(name) FROM storage.objects WHERE bucket_id = 'portfolio-completed' AND name LIKE v_uid::text || '/%'), '{}'),
    'verification-docs',   COALESCE((SELECT array_agg(name) FROM storage.objects WHERE bucket_id = 'verification-docs' AND name LIKE 'verification/' || v_uid::text || '/%'), '{}'),
    'work-orders',         COALESCE((
      SELECT array_agg(o.name) FROM storage.objects o
      WHERE o.bucket_id = 'work-orders'
        AND EXISTS (
          SELECT 1 FROM work_orders wo
          WHERE (wo.customer_id = v_uid OR wo.contractor_id = v_uid)
            AND o.name LIKE wo.id::text || '/%'
        )
    ), '{}')
  ) INTO v_storage;

  DELETE FROM auth.identities WHERE user_id = v_uid;
  DELETE FROM auth.sessions WHERE user_id = v_uid;
  DELETE FROM auth.refresh_tokens WHERE user_id = v_uid::text;

  IF v_is_customer THEN
    UPDATE users SET
      full_name = 'Deleted User',
      username = 'deleted-' || substr(v_uid::text, 1, 8),
      email = 'deleted-' || v_uid::text || '@invalid',
      phone = NULL, avatar_url = NULL, location = NULL, lat = NULL, lng = NULL,
      last_location_update = NULL, push_token = NULL,
      referral_source = NULL, referral_code = NULL,
      two_factor_phone = NULL, two_factor_enabled = false,
      deleted_at = now()
    WHERE id = v_uid;
  END IF;

  IF v_is_contractor THEN
    UPDATE contractors SET
      company_name = 'Deleted Contractor', legal_name = NULL,
      username = 'deleted-' || substr(v_uid::text, 1, 8),
      email = 'deleted-' || v_uid::text || '@invalid',
      phone = NULL, avatar = NULL, avatar_url = NULL, banner_url = NULL,
      website = NULL, tagline = NULL, description = NULL, experience = NULL,
      location = NULL, address = NULL, business_city = NULL, business_state = NULL,
      service_area = NULL, service_areas = NULL,
      license_number = NULL, license_expiration = NULL, license_county = NULL,
      license_state = NULL, license_url = NULL, insurance_url = NULL,
      lat = NULL, lng = NULL, commercial_lat = NULL, commercial_lng = NULL,
      service_area_lat = NULL, service_area_lng = NULL, last_location_update = NULL,
      push_token = NULL, company_tag = NULL, company_pin_hash = NULL,
      is_available = false, is_online = false, show_on_map = false,
      profile_published = false, accepts_bookings = false,
      deleted_at = now()
    WHERE id = v_uid;
  END IF;

  RETURN jsonb_build_object(
    'processed', true,
    'user_id', v_uid,
    'role', v_req.role,
    'is_customer', v_is_customer,
    'is_contractor', v_is_contractor,
    'storage_targets', v_storage
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.protect_contractor_billing_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_scope text := current_setting('app.bypass_protection', true);
begin
  if auth.uid() is not null then
    if new.plan is distinct from old.plan and v_scope is distinct from 'plan' then
      raise exception 'Plan and billing fields can only be updated by the system'
        using errcode = 'TE001';
    end if;
    if new.stripe_customer_id is distinct from old.stripe_customer_id
       or new.stripe_subscription_id is distinct from old.stripe_subscription_id
    then
      raise exception 'Plan and billing fields can only be updated by the system'
        using errcode = 'TE001';
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.protect_contractor_columns()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_scope text := current_setting('app.bypass_protection', true);
BEGIN
  IF auth.role() = 'authenticated' THEN
    IF NEW.plan IS DISTINCT FROM OLD.plan AND v_scope IS DISTINCT FROM 'plan' THEN
      RAISE EXCEPTION 'plan cannot be changed directly; use the billing/upgrade flow' USING ERRCODE = '42501';
    END IF;
    IF NEW.rating IS DISTINCT FROM OLD.rating AND v_scope IS DISTINCT FROM 'rating' THEN
      RAISE EXCEPTION 'rating cannot be changed directly; submit a review instead' USING ERRCODE = '42501';
    END IF;
    IF NEW.review_count IS DISTINCT FROM OLD.review_count AND v_scope IS DISTINCT FROM 'rating' THEN
      RAISE EXCEPTION 'review_count cannot be changed directly' USING ERRCODE = '42501';
    END IF;
    IF NEW.verified IS DISTINCT FROM OLD.verified AND v_scope IS DISTINCT FROM 'verification' THEN
      RAISE EXCEPTION 'verified cannot be set directly' USING ERRCODE = '42501';
    END IF;
    IF NEW.license_verified IS DISTINCT FROM OLD.license_verified AND v_scope IS DISTINCT FROM 'verification' THEN
      RAISE EXCEPTION 'license_verified cannot be set directly' USING ERRCODE = '42501';
    END IF;
    IF NEW.insurance_verified IS DISTINCT FROM OLD.insurance_verified AND v_scope IS DISTINCT FROM 'verification' THEN
      RAISE EXCEPTION 'insurance_verified cannot be set directly' USING ERRCODE = '42501';
    END IF;
    IF NEW.insured IS DISTINCT FROM OLD.insured AND v_scope IS DISTINCT FROM 'verification' THEN
      RAISE EXCEPTION 'insured cannot be set directly' USING ERRCODE = '42501';
    END IF;
    IF NEW.verification_status IS DISTINCT FROM OLD.verification_status
       AND NEW.verification_status != 'pending_review'
       AND v_scope IS DISTINCT FROM 'verification' THEN
      RAISE EXCEPTION 'verification_status can only be self-set to pending_review' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.public_contractor_location(p_lat double precision, p_lng double precision, p_service_radius_miles numeric, p_area_name text, p_show_exact_location boolean, p_has_commercial_address boolean, p_commercial_lat double precision, p_commercial_lng double precision)
 RETURNS TABLE(pin_lat double precision, pin_lng double precision, pin_mode text, service_radius_miles numeric, area_label text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  SELECT
    CASE WHEN x.exact_allowed THEN p_commercial_lat ELSE p_lat END,
    CASE WHEN x.exact_allowed THEN p_commercial_lng ELSE p_lng END,
    CASE WHEN x.exact_allowed THEN 'storefront' ELSE 'service_area' END,
    CASE WHEN x.exact_allowed THEN NULL::numeric ELSE p_service_radius_miles END,
    CASE WHEN x.exact_allowed THEN COALESCE(p_area_name, 'this area')
         ELSE 'Serves ' || COALESCE(p_area_name, 'this area') || ' and nearby' END
  FROM (
    SELECT p_show_exact_location AND p_has_commercial_address
      AND p_commercial_lat IS NOT NULL AND p_commercial_lng IS NOT NULL AS exact_allowed
  ) x;
$function$;


CREATE OR REPLACE FUNCTION public.public_job_by_id(job_id uuid)
 RETURNS TABLE(id uuid, trade text, description text, urgency text, status text, price_estimate integer, created_at timestamp with time zone, request_expires_at timestamp with time zone, fuzzed_lat double precision, fuzzed_lng double precision, town text, nearest_major_road text, is_instant_book boolean, instant_book_price integer, is_quote_locked boolean, quote_locked_until timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    b.id,
    b.trade,
    b.description,
    b.urgency,
    b.status,
    b.price_estimate,
    b.created_at,
    b.request_expires_at,
    fz.fuzzed_lat,
    fz.fuzzed_lng,
    b.town,
    b.nearest_major_road,
    b.is_instant_book,
    b.instant_book_price,
    ao.offer_status IS NOT NULL AS is_quote_locked,
    CASE WHEN ao.offer_status = 'countered' THEN COALESCE(ao.counter_expires_at, ao.expires_at) ELSE ao.expires_at END AS quote_locked_until
  FROM public.bookings b
  CROSS JOIN LATERAL public.fuzz_point(b.id, b.job_lat::double precision, b.job_lng::double precision, 600) fz
  LEFT JOIN LATERAL (
    SELECT jo.status AS offer_status, jo.expires_at, jo.counter_expires_at
    FROM public.job_offers jo
    WHERE jo.booking_id = b.id AND jo.status IN ('quoted', 'countered')
    ORDER BY jo.offered_at DESC
    LIMIT 1
  ) ao ON true
  WHERE b.id = job_id
    AND b.status = 'pending'
    AND b.contractor_id IS NULL
    AND b.is_public = true
    AND (b.request_expires_at IS NULL OR b.request_expires_at > now())
    AND b.job_lat IS NOT NULL
    AND b.job_lng IS NOT NULL;
$function$;


CREATE OR REPLACE FUNCTION public.public_jobs_nearby(user_lat double precision, user_lng double precision, max_miles double precision DEFAULT 50, trade_filter text DEFAULT NULL::text, trade_filter_ids text[] DEFAULT NULL::text[])
 RETURNS TABLE(id uuid, trade text, description text, urgency text, status text, price_estimate integer, created_at timestamp with time zone, request_expires_at timestamp with time zone, fuzzed_lat double precision, fuzzed_lng double precision, town text, nearest_major_road text, is_instant_book boolean, instant_book_price integer, is_quote_locked boolean, quote_locked_until timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    b.id,
    b.trade,
    b.description,
    b.urgency,
    b.status,
    b.price_estimate,
    b.created_at,
    b.request_expires_at,
    fz.fuzzed_lat,
    fz.fuzzed_lng,
    b.town,
    b.nearest_major_road,
    b.is_instant_book,
    b.instant_book_price,
    ao.offer_status IS NOT NULL AS is_quote_locked,
    CASE WHEN ao.offer_status = 'countered' THEN COALESCE(ao.counter_expires_at, ao.expires_at) ELSE ao.expires_at END AS quote_locked_until
  FROM public.bookings b
  CROSS JOIN LATERAL public.fuzz_point(b.id, b.job_lat::double precision, b.job_lng::double precision, 600) fz
  LEFT JOIN LATERAL (
    SELECT jo.status AS offer_status, jo.expires_at, jo.counter_expires_at
    FROM public.job_offers jo
    WHERE jo.booking_id = b.id AND jo.status IN ('quoted', 'countered')
    ORDER BY jo.offered_at DESC
    LIMIT 1
  ) ao ON true
  WHERE b.status = 'pending'
    AND b.contractor_id IS NULL
    AND b.is_public = true
    AND (b.request_expires_at IS NULL OR b.request_expires_at > now())
    AND b.job_lat IS NOT NULL
    AND b.job_lng IS NOT NULL
    AND (trade_filter IS NULL OR b.trade = trade_filter)
    AND (trade_filter_ids IS NULL OR b.trade = ANY(trade_filter_ids))
    AND public.haversine_miles(user_lat, user_lng, b.job_lat::double precision, b.job_lng::double precision) <= max_miles
  ORDER BY b.created_at DESC
  LIMIT 200;
$function$;


CREATE OR REPLACE FUNCTION public.recalc_work_order_billing()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_subtotal  NUMERIC := 0;
  v_fee_rate  NUMERIC;
  v_fee       NUMERIC;
  v_tax_rate  NUMERIC := 0.08875;
  v_tax       NUMERIC;
  v_item      JSONB;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(NEW.line_items)
  LOOP
    v_subtotal := v_subtotal + COALESCE((v_item->>'amount')::NUMERIC, 0);
  END LOOP;

  IF    v_subtotal <= 500  THEN v_fee_rate := 0.20;
  ELSIF v_subtotal <= 2000 THEN v_fee_rate := 0.15;
  ELSE                          v_fee_rate := 0.10;
  END IF;

  v_fee := ROUND(v_subtotal * v_fee_rate, 2);
  v_tax := ROUND(v_subtotal * v_tax_rate, 2);

  NEW.billing := jsonb_build_object(
    'subtotal',  v_subtotal,
    'feeRate',   v_fee_rate,
    'feeAmount', v_fee,
    'taxRate',   v_tax_rate,
    'taxAmount', v_tax,
    'total',     ROUND(v_subtotal + v_fee + v_tax, 2)
  );

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.release_payment_on_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  -- Only fire when status changes to 'completed'
  if old.status != 'completed' and new.status = 'completed' then
    -- Mark payment as ready to release
    if new.payment_status = 'held' then
      new.payment_status := 'released';
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.restrict_booking_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
-- Contractor cannot reassign customer, reassign contractor, or revert to pending
IF auth.uid() = OLD.contractor_id THEN
IF NEW.customer_id IS DISTINCT FROM OLD.customer_id THEN
RAISE EXCEPTION 'Cannot change customer on a booking';
END IF;
IF NEW.contractor_id IS DISTINCT FROM OLD.contractor_id THEN
RAISE EXCEPTION 'Cannot reassign contractor';
END IF;
IF NEW.status = 'pending' AND OLD.status != 'pending' THEN
RAISE EXCEPTION 'Cannot revert booking to pending';
END IF;
END IF;
-- Customer cannot reassign an existing contractor, cannot assign a
-- contractor with no matching offer, and cannot steal back a confirmed job
IF auth.uid() = OLD.customer_id THEN
IF NEW.contractor_id IS DISTINCT FROM OLD.contractor_id THEN
IF OLD.contractor_id IS NOT NULL THEN
RAISE EXCEPTION 'Cannot change contractor on a booking';
ELSIF NEW.contractor_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.job_offers
  WHERE booking_id = OLD.id AND contractor_id = NEW.contractor_id
) THEN
RAISE EXCEPTION 'Cannot assign a contractor without a matching offer';
END IF;
END IF;
IF OLD.status IN ('accepted','confirmed','in_progress') AND NEW.status = 'pending' THEN
RAISE EXCEPTION 'Cannot revert an active booking to pending';
END IF;
END IF;
RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.restrict_contractor_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (NEW.is_available = true OR NEW.is_online = true)
     AND NEW.verification_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'Cannot go online until verification is approved' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;


CREATE OR REPLACE FUNCTION public.save_contractor_trades(p_trade_ids text[], p_primary_trade_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_trade_ids IS NULL OR array_length(p_trade_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one trade is required' USING ERRCODE = 'P0001';
  END IF;
  IF p_primary_trade_id IS NULL OR NOT (p_primary_trade_id = ANY(p_trade_ids)) THEN
    RAISE EXCEPTION 'Primary trade must be one of the selected trades' USING ERRCODE = 'P0001';
  END IF;

  UPDATE contractor_trades SET is_primary = false
  WHERE contractor_id = auth.uid() AND is_primary = true;

  DELETE FROM contractor_trades
  WHERE contractor_id = auth.uid() AND NOT (trade_id = ANY(p_trade_ids));

  INSERT INTO contractor_trades (contractor_id, trade_id, is_primary, sort_order)
  SELECT auth.uid(), t.id, (t.id = p_primary_trade_id), t.sort_order
  FROM trades t
  WHERE t.id = ANY(p_trade_ids)
  ON CONFLICT (contractor_id, trade_id) DO UPDATE
    SET is_primary = EXCLUDED.is_primary, sort_order = EXCLUDED.sort_order;
END;
$function$;


CREATE OR REPLACE FUNCTION public.save_payment_method(p_payment_method_id text)
