CREATE OR REPLACE FUNCTION public.set_auto_approve_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
    NEW.completed_at    := NOW();
    NEW.auto_approve_at := NOW() + INTERVAL '24 hours';
  END IF;
  IF NEW.status = 'payment_releasing' AND OLD.status != 'payment_releasing' THEN
    NEW.approved_at := NOW();
  END IF;
  RETURN NEW;
END;
$function$;


