CREATE OR REPLACE FUNCTION public.submit_quote(p_booking_id uuid, p_quoted_price numeric, p_quote_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_offer_id UUID;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM bookings WHERE id = p_booking_id AND status = 'pending') THEN
    RAISE EXCEPTION 'Job is no longer available';
  END IF;
  IF EXISTS (
    SELECT 1 FROM job_offers
    WHERE booking_id = p_booking_id AND contractor_id = auth.uid()
      AND status NOT IN ('declined', 'expired', 'cancelled')
  ) THEN
    RAISE EXCEPTION 'You already submitted a quote for this job';
  END IF;
  IF EXISTS (
    SELECT 1 FROM job_offers
    WHERE booking_id = p_booking_id AND contractor_id != auth.uid()
      AND status IN ('quoted', 'countered')
  ) THEN
    RAISE EXCEPTION 'This job already has an active quote from another contractor' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO job_offers (
    booking_id, contractor_id, quoted_price, quote_note,
    status, customer_action, contractor_final, initiated_by, expires_at
  ) VALUES (
    p_booking_id, auth.uid(), p_quoted_price, p_quote_note,
    'quoted', 'pending', 'pending', 'contractor', NOW() + INTERVAL '24 hours'
  ) RETURNING id INTO v_offer_id;
  RETURN v_offer_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public.submit_review(p_booking_id uuid, p_rating integer, p_review_text text DEFAULT NULL::text)
 RETURNS reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booking       RECORD;
  v_reviewer_name TEXT;
  v_review        public.reviews;
  v_new_avg       NUMERIC;
  v_new_count     INTEGER;
BEGIN
  SELECT * INTO v_booking FROM public.bookings WHERE id = p_booking_id;

  IF v_booking IS NULL THEN
    RAISE EXCEPTION 'Booking not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.customer_id != auth.uid() THEN
    RAISE EXCEPTION 'Only the customer on this booking can leave a review' USING ERRCODE = '42501';
  END IF;

  IF v_booking.status NOT IN ('completed', 'approved') THEN
    RAISE EXCEPTION 'Reviews can only be submitted for completed or approved bookings' USING ERRCODE = '42501';
  END IF;

  IF p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5' USING ERRCODE = '22023';
  END IF;

  SELECT full_name INTO v_reviewer_name FROM public.users WHERE id = auth.uid();

  PERFORM set_config('app.bypass_protection', 'rating', true);

  INSERT INTO public.reviews (booking_id, contractor_id, customer_id, reviewer_name, rating_overall, review_text)
  VALUES (p_booking_id, v_booking.contractor_id, auth.uid(), COALESCE(v_reviewer_name, 'Customer'), p_rating, p_review_text)
  RETURNING * INTO v_review;

  SELECT AVG(rating_overall), COUNT(*) INTO v_new_avg, v_new_count
  FROM public.reviews
  WHERE contractor_id = v_booking.contractor_id AND flagged = false;

  UPDATE public.contractors
  SET rating = ROUND(v_new_avg, 2), review_count = v_new_count
  WHERE id = v_booking.contractor_id;

  RETURN v_review;
END;
$function$;


CREATE OR REPLACE FUNCTION public.sweep_account_deletions()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_req RECORD;
  v_internal_secret text;
BEGIN
  SELECT decrypted_secret INTO v_internal_secret
  FROM vault.decrypted_secrets WHERE name = 'internal_secret';

  FOR v_req IN
    SELECT id FROM public.account_deletion_requests
    WHERE status = 'pending' AND scheduled_delete_at <= now()
  LOOP
    PERFORM net.http_post(
      url := 'https://linqsojbszglbgpoxgtv.supabase.co/functions/v1/process-account-deletions',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-tradease-internal', v_internal_secret
      ),
      body := jsonb_build_object('request_id', v_req.id),
      timeout_milliseconds := 30000
    );
  END LOOP;
END;
$function$;


CREATE OR REPLACE FUNCTION public.sweep_auto_approve_work_orders()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wo RECORD;
  v_internal_secret text;
BEGIN
  SELECT decrypted_secret INTO v_internal_secret
  FROM vault.decrypted_secrets WHERE name = 'internal_secret';

  FOR v_wo IN
    SELECT id FROM public.work_orders
    WHERE status = 'completed'
      AND auto_approve_at IS NOT NULL
      AND auto_approve_at <= NOW()
  LOOP
    -- Mark approved first so the charge function accepts it
    UPDATE public.work_orders SET status = 'approved' WHERE id = v_wo.id;

    -- Call charge-customer via pg_net
    PERFORM net.http_post(
      url := 'https://linqsojbszglbgpoxgtv.supabase.co/functions/v1/charge-customer',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-tradease-internal', v_internal_secret
      ),
      body := jsonb_build_object('work_order_id', v_wo.id::text)
    );

    RAISE NOTICE 'Auto-approved work order %', v_wo.id;
  END LOOP;
END;
$function$;


CREATE OR REPLACE FUNCTION public.sweep_expired_quotes()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_offer RECORD;
  v_booking public.bookings;
  v_contractor_name text;
BEGIN
  FOR v_offer IN
    SELECT * FROM public.job_offers
    WHERE (status = 'quoted' AND expires_at IS NOT NULL AND expires_at <= NOW())
       OR (status = 'countered' AND counter_expires_at IS NOT NULL AND counter_expires_at <= NOW())
  LOOP
    UPDATE public.job_offers SET status = 'expired' WHERE id = v_offer.id;

    SELECT * INTO v_booking FROM public.bookings WHERE id = v_offer.booking_id;
    SELECT company_name INTO v_contractor_name FROM public.contractors WHERE id = v_offer.contractor_id;

    IF v_booking.customer_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, title, message, type, booking_id, data)
      VALUES (
        v_booking.customer_id,
        '⏱ Quote Expired',
        COALESCE(v_contractor_name, 'A contractor') || '''s quote on your ' ||
          COALESCE(v_booking.trade, 'job') || ' job expired without a response. The job is open again.',
        'quote_expired',
        v_offer.booking_id,
        jsonb_build_object('offer_id', v_offer.id, 'trade', v_booking.trade)
      );
    END IF;

    IF v_offer.contractor_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, title, message, type, booking_id, data)
      VALUES (
        v_offer.contractor_id,
        '⏱ Quote Expired',
        'Your quote on the ' || COALESCE(v_booking.trade, '') || ' job went unanswered and expired.',
        'quote_expired',
        v_offer.booking_id,
        jsonb_build_object('offer_id', v_offer.id, 'trade', v_booking.trade)
      );
    END IF;
  END LOOP;
END;
$function$;


CREATE OR REPLACE FUNCTION public.sweep_overnight_job_emails()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booking RECORD;
BEGIN
  IF NOT public._within_working_hours() THEN
    RETURN;
  END IF;

  FOR v_booking IN
    SELECT id FROM public.bookings
    WHERE job_email_sent_at IS NULL
      AND contractor_id IS NULL
      AND status = 'pending'
  LOOP
    PERFORM public._send_new_job_email(v_booking.id);
  END LOOP;
END;
$function$;


