CREATE OR REPLACE FUNCTION public.sync_verification_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.approved = true AND OLD.approved = false THEN
    NEW.verification_status    := 'approved';
    NEW.verified               := true;
    NEW.license_verified       := true;
    NEW.insurance_verified     := true;
    NEW.verification_reviewed_at := NOW();
  END IF;
  IF NEW.verification_status = 'pending_review' AND OLD.verification_status != 'pending_review' THEN
    NEW.verification_submitted_at := NOW();
  END IF;
  RETURN NEW;
END;
$function$;


