CREATE OR REPLACE FUNCTION public.validate_and_fill_message()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_parts TEXT[];
  v_uid1 UUID;
  v_uid2 UUID;
BEGIN
  IF NEW.chat_id IS NOT NULL THEN
    v_parts := string_to_array(NEW.chat_id, '_');
    IF array_length(v_parts, 1) = 2 THEN
      BEGIN
        v_uid1 := v_parts[1]::UUID;
        v_uid2 := v_parts[2]::UUID;
      EXCEPTION WHEN OTHERS THEN
        v_uid1 := NULL; v_uid2 := NULL;
      END;

      IF v_uid1 IS NOT NULL AND v_uid2 IS NOT NULL THEN
        IF NEW.sender_id != v_uid1 AND NEW.sender_id != v_uid2 THEN
          RAISE EXCEPTION 'sender_id is not part of this chat_id pair' USING ERRCODE = '42501';
        END IF;
        IF NEW.recipient_id IS NULL THEN
          NEW.recipient_id := CASE WHEN v_uid1 = NEW.sender_id THEN v_uid2 ELSE v_uid1 END;
        END IF;
      END IF;
    END IF;
  END IF;

  IF NEW.read IS NULL THEN
    NEW.read := false;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.validate_counter_price()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.counter_price IS NOT NULL AND NEW.quoted_price IS NOT NULL THEN
    IF NEW.counter_price < NEW.quoted_price * 0.70 THEN
      RAISE EXCEPTION 'Counter offer must be at least 70%% of quoted price ($%)',
        ROUND((NEW.quoted_price * 0.70)::numeric, 2);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.validate_negotiation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Enforce price floor: customer counter must be >= 70% of quoted_price
  IF NEW.customer_action = 'countered' AND NEW.counter_price IS NOT NULL AND OLD.quoted_price IS NOT NULL THEN
    IF NEW.counter_price < (OLD.quoted_price * 0.70) THEN
      RAISE EXCEPTION 'Counter offer must be at least 70%% of the contractor''s quoted price ($%)',
        ROUND(OLD.quoted_price * 0.70);
    END IF;
    -- Set counter expiry to 2 hours from now
    NEW.counter_expires_at := now() + INTERVAL '2 hours';
    NEW.status := 'countered';
  END IF;

  -- Contractor accepting counter: set final price
  IF NEW.contractor_final = 'accepted' AND OLD.counter_price IS NOT NULL THEN
    NEW.final_price := OLD.counter_price;
    NEW.status := 'accepted';
  END IF;

  -- Contractor declining counter
  IF NEW.contractor_final = 'declined' THEN
    NEW.status := 'declined';
  END IF;

  -- Customer accepting contractor's quote directly
  IF NEW.customer_action = 'accepted' AND OLD.counter_price IS NULL THEN
    NEW.final_price := OLD.quoted_price;
    NEW.status := 'accepted';
  END IF;

  -- Customer declining
  IF NEW.customer_action = 'declined' THEN
    NEW.status := 'declined';
  END IF;

  NEW.responded_at := now();
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.validate_work_order_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_old_status work_order_status := OLD.status;
  v_new_status work_order_status := COALESCE(NEW.wo_status, NEW.status);
BEGIN
  IF v_old_status = v_new_status THEN RETURN NEW; END IF;

  IF NOT (
    (v_old_status = 'submitted'            AND v_new_status IN ('accepted','cancelled')) OR
    (v_old_status = 'accepted'             AND v_new_status IN ('deposit_secured','en_route','cancelled')) OR
    (v_old_status = 'deposit_secured'      AND v_new_status IN ('en_route','cancelled')) OR
    (v_old_status = 'en_route'             AND v_new_status IN ('arrived','cancelled')) OR
    (v_old_status = 'arrived'              AND v_new_status IN ('in_progress','change_order_pending','cancelled')) OR
    (v_old_status = 'in_progress'          AND v_new_status IN ('waiting_for_customer','materials_needed',
                                           'change_order_pending','awaiting_approval','completed','disputed')) OR
    (v_old_status = 'waiting_for_customer' AND v_new_status IN ('in_progress','change_order_pending','disputed')) OR
    (v_old_status = 'materials_needed'     AND v_new_status IN ('in_progress','change_order_pending','disputed')) OR
    (v_old_status = 'change_order_pending' AND v_new_status IN ('in_progress','awaiting_approval')) OR
    (v_old_status = 'awaiting_approval'    AND v_new_status IN ('payment_releasing','in_progress','disputed')) OR
    (v_old_status = 'payment_releasing'    AND v_new_status IN ('completed')) OR
    (v_old_status = 'disputed'             AND v_new_status IN ('completed','cancelled'))
  ) THEN
    RAISE EXCEPTION 'Invalid work order transition: % → %', v_old_status, v_new_status;
  END IF;

  IF v_new_status = 'completed' AND NEW.payment_intent_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM payment_intents WHERE id = NEW.payment_intent_id AND status = 'captured'
    ) THEN
      RAISE EXCEPTION 'Cannot complete work order: payment must be captured first';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;


-- ============================================================================
-- 9. TRIGGERS
-- ============================================================================

CREATE OR REPLACE TRIGGER enforce_booking_rate_limit BEFORE INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION enforce_booking_rate_limit();

CREATE OR REPLACE TRIGGER guard_booking_update BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION restrict_booking_update();

CREATE OR REPLACE TRIGGER on_booking_cancel BEFORE UPDATE OF status ON public.bookings FOR EACH ROW WHEN (((new.status = ANY (ARRAY['declined'::text, 'cancelled'::text])) AND (old.status <> new.status))) EXECUTE FUNCTION handle_cancellation_and_reassign();

CREATE OR REPLACE TRIGGER on_booking_complete BEFORE UPDATE OF status ON public.bookings FOR EACH ROW EXECUTE FUNCTION handle_booking_completed();

CREATE OR REPLACE TRIGGER on_booking_complete_payment BEFORE UPDATE OF status ON public.bookings FOR EACH ROW EXECUTE FUNCTION release_payment_on_completion();

CREATE OR REPLACE TRIGGER on_booking_contractor_cancel AFTER UPDATE ON public.bookings FOR EACH ROW WHEN (((new.status = 'cancelled'::text) AND (old.status IS DISTINCT FROM 'cancelled'::text))) EXECUTE FUNCTION issue_coupon_on_contractor_cancel();

CREATE OR REPLACE TRIGGER on_booking_created AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_contractor_new_booking();

CREATE OR REPLACE TRIGGER on_booking_created_match AFTER INSERT ON public.bookings FOR EACH ROW WHEN ((new.status = 'pending'::text)) EXECUTE FUNCTION trigger_job_matching();

CREATE OR REPLACE TRIGGER on_booking_status_supplemental AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_booking_status_supplemental();

CREATE OR REPLACE TRIGGER on_booking_status_update_slots AFTER UPDATE OF status ON public.bookings FOR EACH ROW EXECUTE FUNCTION mark_slot_booked();

CREATE OR REPLACE TRIGGER on_employee_job_complete AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION track_employee_job();

CREATE OR REPLACE TRIGGER on_job_accepted AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_job_accepted();

CREATE OR REPLACE TRIGGER on_job_completed AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_job_completed();

CREATE OR REPLACE TRIGGER on_new_job_posted AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_new_job_posted();

CREATE OR REPLACE TRIGGER trg_bookings_updated_at BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE OR REPLACE TRIGGER trg_broadcast_new_job_lead AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION broadcast_new_job_lead();

CREATE OR REPLACE TRIGGER trg_email_job_accepted AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION email_on_job_accepted();

CREATE OR REPLACE TRIGGER trg_email_job_completed AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION email_on_job_completed();

