-- ============================================================================
-- 13. VIEWS
-- ============================================================================

CREATE OR REPLACE VIEW public.admin_analytics AS
 SELECT ( SELECT count(*) AS count
           FROM bookings) AS total_bookings,
    ( SELECT count(*) AS count
           FROM bookings
          WHERE bookings.status = 'completed'::text) AS completed_bookings,
    ( SELECT count(*) AS count
           FROM bookings
          WHERE bookings.created_at > (now() - '7 days'::interval)) AS bookings_this_week,
    ( SELECT count(*) AS count
           FROM contractors
          WHERE COALESCE(contractors.approved, false) = true) AS approved_contractors,
    ( SELECT count(*) AS count
           FROM contractors
          WHERE contractors.approval_status = 'pending'::text) AS pending_approvals,
    ( SELECT count(*) AS count
           FROM users
          WHERE users.role = 'customer'::text) AS total_customers,
    ( SELECT COALESCE(sum(payments.platform_fee), 0::numeric) AS "coalesce"
           FROM payments
          WHERE payments.status = 'captured'::text) AS total_revenue,
    ( SELECT COALESCE(avg(reviews.rating_overall), 0::numeric) AS "coalesce"
           FROM reviews) AS avg_platform_rating,
    ( SELECT count(*) AS count
           FROM payments
          WHERE payments.status = 'disputed'::text) AS open_disputes;

CREATE OR REPLACE VIEW public.booking_calendar AS
 SELECT id,
    customer_id,
    contractor_id,
    contractor_name,
    customer_name,
    trade,
    booking_date,
    booking_time,
    status,
    description,
    completed_at,
    cancelled_at,
    fee_percent,
    EXTRACT(year FROM booking_date) AS booking_year,
    EXTRACT(month FROM booking_date) AS booking_month,
    EXTRACT(day FROM booking_date) AS booking_day,
    to_char(booking_date::timestamp with time zone, 'Mon'::text) AS month_short,
    to_char(booking_date::timestamp with time zone, 'Day'::text) AS day_name
   FROM bookings b
  WHERE status <> ALL (ARRAY['cancelled'::text, 'declined'::text]);

CREATE OR REPLACE VIEW public.contractor_earnings AS
 SELECT contractor_id,
    sum(
        CASE
            WHEN completed_at::date = CURRENT_DATE THEN COALESCE(contractor_payout, final_price::numeric, price_estimate::numeric, 0::numeric)
            ELSE 0::numeric
        END) AS today,
    sum(
        CASE
            WHEN completed_at >= date_trunc('week'::text, now()) THEN COALESCE(contractor_payout, final_price::numeric, price_estimate::numeric, 0::numeric)
            ELSE 0::numeric
        END) AS this_week,
    sum(
        CASE
            WHEN completed_at >= date_trunc('month'::text, now()) THEN COALESCE(contractor_payout, final_price::numeric, price_estimate::numeric, 0::numeric)
            ELSE 0::numeric
        END) AS this_month,
    count(
        CASE
            WHEN completed_at::date = CURRENT_DATE THEN 1
            ELSE NULL::integer
        END) AS jobs_today,
    count(
        CASE
            WHEN completed_at >= date_trunc('week'::text, now()) THEN 1
            ELSE NULL::integer
        END) AS jobs_this_week,
    count(
        CASE
            WHEN status = 'confirmed'::text AND contractor_id IS NOT NULL THEN 1
            ELSE NULL::integer
        END) AS active_jobs
   FROM bookings
  WHERE status = ANY (ARRAY['completed'::text, 'confirmed'::text])
  GROUP BY contractor_id;

CREATE OR REPLACE VIEW public.contractor_profiles AS
 SELECT c.id,
    c.company_name,
    c.trade_type,
    c.location,
    c.description,
    c.rating,
    c.review_count,
    c.plan,
    c.verified,
    c.approved,
    c.accepts_bookings,
    c.avatar_url,
    c.banner_url,
    c.portfolio,
    c.pricing_services,
    c.insured,
    c.experience,
    c.service_areas,
    c.is_online,
    c.profile_views,
    c.total_bookings,
    c.phone,
    c.email,
    c.website,
    c.pricing_note,
    c.hourly_rate,
    u.username,
    u.full_name,
    c.created_at
   FROM contractors c
     LEFT JOIN users u ON u.id = c.id
  WHERE c.approved = true;

CREATE OR REPLACE VIEW public.contractor_team_summary AS
 SELECT contractor_id,
    count(*) FILTER (WHERE status = 'active'::text) AS active_count,
    count(*) FILTER (WHERE status = 'invited'::text) AS pending_count,
    count(*) FILTER (WHERE status = ANY (ARRAY['active'::text, 'invited'::text])) AS total_used,
    sum(jobs_completed) AS team_jobs_total
   FROM contractor_employees
  GROUP BY contractor_id;

CREATE OR REPLACE VIEW public.contractors_missing_trades AS
 SELECT id,
    company_name,
    email,
    verification_status,
    created_at
   FROM contractors c
  WHERE verification_status = 'approved'::text AND NOT (EXISTS ( SELECT 1
           FROM contractor_trades ct
          WHERE ct.contractor_id = c.id))
  ORDER BY created_at DESC;

CREATE OR REPLACE VIEW public.contractors_public AS
 SELECT c.id,
    c.username,
    c.company_name,
    c.company_tag,
    c.tagline,
    c.trade_type,
    c.description,
    c.experience,
    c.years_in_business,
    c.specializations,
    c.languages,
    c.service_area,
    c.service_areas,
    c.service_radius_miles,
    c.location,
    c.business_city,
    c.business_state,
    c.show_on_map,
    c.location_mode,
    c.avatar,
    c.avatar_url,
    c.banner_url,
    c.portfolio,
    c.portfolio_photos,
    c.pricing_services,
    c.pricing_note,
    c.pricing_desc,
    c.hourly_rate,
    c.rating,
    c.review_count,
    c.total_bookings,
    c.response_time_avg,
    c.acceptance_rate,
    c.reliability_score,
    c.verified,
    c.license_verified,
    c.insurance_verified,
    c.insured,
    c.is_online,
    c.is_available,
    c.accepts_bookings,
    c.profile_complete,
    c.profile_published,
    c.created_at,
    c.website,
    c.plan,
    c.verification_status,
    c.phone,
    COALESCE(array_agg(ct.trade_id) FILTER (WHERE ct.trade_id IS NOT NULL), '{}'::text[]) AS trade_ids
   FROM contractors c
     LEFT JOIN contractor_trades ct ON ct.contractor_id = c.id
  WHERE c.deleted_at IS NULL
  GROUP BY c.id;

CREATE OR REPLACE VIEW public.portfolio_jobs_public AS
 SELECT id,
    contractor_id,
    title,
    service_type,
    description,
    general_location,
    completed_price,
    completed_at,
    photos,
    created_at
   FROM portfolio_jobs
  WHERE is_published = true;

CREATE OR REPLACE VIEW public.refund_summary AS
 SELECT rr.id,
    rr.status,
    rr.reason,
    rr.amount_paid,
    rr.amount_requested,
    rr.amount_approved,
    rr.created_at,
    rr.reviewed_at,
    b.booking_date,
    b.booking_time,
    b.contractor_name,
    b.customer_name,
    b.trade
   FROM refund_requests rr
     JOIN bookings b ON b.id = rr.booking_id;


