DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'auto-approve-work-orders') THEN
    PERFORM cron.schedule('auto-approve-work-orders', '*/15 * * * *', 'SELECT public.sweep_auto_approve_work_orders()');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'sweep-expired-quotes') THEN
    PERFORM cron.schedule('sweep-expired-quotes', '*/15 * * * *', 'SELECT public.sweep_expired_quotes()');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'sweep-overnight-job-emails') THEN
    PERFORM cron.schedule('sweep-overnight-job-emails', '*/15 * * * *', 'SELECT public.sweep_overnight_job_emails()');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'sweep-account-deletions') THEN
    PERFORM cron.schedule('sweep-account-deletions', '0 * * * *', 'SELECT public.sweep_account_deletions()');
  END IF;
END $$;


